"use client";

import { ArrowUpIcon } from "lucide-react";
import type { ReactElement, RefObject } from "react";
import { useId, useMemo } from "react";
import { useMediaQuery } from "@/registry/default/hooks/use-media-query";
import { cn } from "@/registry/default/lib/utils";
import { Button } from "@/registry/default/ui/button";
import {
  Composer,
  ComposerActionGroup,
  ComposerActions,
  ComposerInput,
  ComposerItem,
  type ComposerItemValue,
  ComposerList,
  ComposerPopup,
  ComposerSubmit,
  type ComposerTrigger,
  type ComposerValue,
} from "@/registry/default/ui/composer";
import {
  Tooltip,
  TooltipPopup,
  TooltipTrigger,
} from "@/registry/default/ui/tooltip";
import { ChatMemberAvatar } from "./chat-demo-message";
import type { MemberId } from "./chat-demo-state";
import { CHAT_MEMBERS } from "./chat-demo-state";

function isMemberId(id: string): id is MemberId {
  return Object.hasOwn(CHAT_MEMBERS, id);
}

function mentionMatchesHandle(item: ComposerItemValue, query: string): boolean {
  return item.label.toLocaleLowerCase().startsWith(query.toLocaleLowerCase());
}

export function ChatDemoComposer({
  className,
  value,
  onValueChange,
  replyAuthor,
  mentionMembers,
  onSend,
  inputRef,
  notice,
  disabled = false,
}: {
  className?: string;
  value: ComposerValue;
  onValueChange: (value: ComposerValue) => void;
  replyAuthor?: string;
  mentionMembers: readonly MemberId[];
  onSend: () => void;
  inputRef: RefObject<HTMLDivElement | null>;
  notice: string;
  disabled?: boolean;
}): ReactElement {
  const hintId = useId();
  const touchInput = useMediaQuery({ pointer: "coarse" });
  const triggers = useMemo<ComposerTrigger[]>(
    () => [
      {
        character: "@",
        filter: mentionMatchesHandle,
        items: mentionMembers.map((id) => ({
          id,
          label: CHAT_MEMBERS[id].handle,
        })),
      },
    ],
    [mentionMembers],
  );

  return (
    <div
      className={cn(
        "relative z-20 flex shrink-0 flex-col gap-2.5 px-4 pb-[max(1rem,env(safe-area-inset-bottom,0px))]",
        className,
      )}
    >
      <Composer
        className="[--composer-max-rows:4] data-disabled:opacity-50 max-md:data-[layout=adaptive]:not-data-multiline:px-1 max-md:[--composer-min-rows:1] max-md:[--composer-padding:--spacing(1)] max-md:[--composer-radius:calc(--spacing(5.5)+1px)] sm:max-md:[--composer-radius:calc(--spacing(5)+1px)] md:[--composer-max-rows:6] md:[--composer-min-rows:2] pointer-coarse:[&_[data-slot=composer-scroll-area]_[data-slot=scroll-area-scrollbar]]:hidden"
        disabled={disabled}
        layout="adaptive"
        submitOnEnter="desktop"
        triggers={triggers}
        value={value}
        onSubmit={onSend}
        onValueChange={onValueChange}
      >
        <ComposerInput
          ref={inputRef}
          aria-describedby={touchInput ? undefined : hintId}
          aria-label="Message"
          className="max-md:px-2"
          placeholder={
            replyAuthor ? `Reply to ${replyAuthor}…` : "Message the group…"
          }
        />
        <ComposerPopup>
          <ComposerList>
            {(item: ComposerItemValue) => {
              if (!isMemberId(item.id)) return null;
              return (
                <ComposerItem key={item.id} value={item}>
                  <ChatMemberAvatar
                    className="size-4 text-[0.5rem]"
                    member={item.id}
                  />
                  <span className="min-w-0 truncate">
                    {CHAT_MEMBERS[item.id].name}
                  </span>
                </ComposerItem>
              );
            }}
          </ComposerList>
        </ComposerPopup>
        <ComposerActions className="max-md:mx-1">
          <ComposerActionGroup align="end">
            <Tooltip>
              <ComposerSubmit
                aria-label="Send message"
                render={
                  <TooltipTrigger
                    render={
                      <Button
                        aria-label="Send message"
                        className="rounded-full before:rounded-full"
                        size="icon"
                      >
                        <ArrowUpIcon
                          aria-hidden="true"
                          className="size-4 md:size-4.5"
                        />
                      </Button>
                    }
                  />
                }
              />
              <TooltipPopup side="bottom">Send message</TooltipPopup>
            </Tooltip>
          </ComposerActionGroup>
        </ComposerActions>
      </Composer>
      <div
        className={cn(
          touchInput && !notice
            ? "sr-only"
            : "flex min-h-4 items-center justify-between px-1 text-muted-foreground text-xs",
          disabled && "opacity-50",
        )}
      >
        <span aria-live="polite" role="status">
          {notice}
        </span>
        {!touchInput && (
          <span
            className={notice ? "sr-only" : "ms-auto pointer-coarse:hidden"}
            id={hintId}
          >
            Enter to send <span className="px-1.5 opacity-40">/</span> Shift +
            Enter for a new line
          </span>
        )}
      </div>
    </div>
  );
}

"use client";

import { ArrowLeftIcon, CheckCheckIcon, ClockIcon } from "lucide-react";
import type { ReactElement, RefObject } from "react";
import { useRef } from "react";
import { cn } from "@/registry/default/lib/utils";
import { Button } from "@/registry/default/ui/button";
import {
  Drawer,
  DrawerClose,
  DrawerDescription,
  DrawerHeader,
  DrawerPanel,
  DrawerPopup,
  DrawerTitle,
} from "@/registry/default/ui/drawer";
import { ChatDeliveryIndicator } from "../chat/chat-delivery-indicator";
import { ChatMessageBubble } from "../chat/chat-message-bubble";
import { ChatMessageInfo as ChatMessageInfoView } from "../chat/chat-message-info";
import { ChatDemoMessageBody, ChatMemberAvatar } from "./chat-demo-message";
import {
  DELIVERY_LABELS,
  getMessageDelivery,
  groupMessageReceipts,
} from "./chat-demo-receipts";
import type { ChatMessage, MemberId } from "./chat-demo-state";
import { CHAT_MEMBERS } from "./chat-demo-state";

const RECEIPT_SECTIONS = [
  { key: "read", label: "Read by", icon: CheckCheckIcon },
  {
    key: "delivered",
    label: "Delivered to",
    icon: CheckCheckIcon,
  },
  {
    key: "pending",
    label: "Pending delivery",
    icon: ClockIcon,
  },
] as const;

export function ChatMessageInfo({
  message,
  recipients,
  replyMessage,
  position,
  open,
  onOpenChange,
  onClosed,
  returnFocusRef,
}: {
  message?: ChatMessage;
  recipients: readonly MemberId[];
  replyMessage?: ChatMessage;
  position: "bottom" | "right";
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onClosed: () => void;
  returnFocusRef: RefObject<HTMLElement | null>;
}): ReactElement {
  const backRef = useRef<HTMLButtonElement>(null);
  const groups = message
    ? groupMessageReceipts(message, recipients)
    : { read: [], delivered: [], pending: [] };
  const visibleSections = RECEIPT_SECTIONS.filter(
    ({ key }) => groups[key].length > 0,
  );
  const delivery = message ? getMessageDelivery(message, recipients) : "sent";
  return (
    <Drawer
      position={position}
      open={open}
      onOpenChange={onOpenChange}
      onOpenChangeComplete={(isOpen) => {
        if (!isOpen) onClosed();
      }}
    >
      {message && (
        <DrawerPopup
          variant="inset"
          initialFocus={backRef}
          finalFocus={returnFocusRef}
          className={
            position === "bottom" ? "[--drawer-height:92dvh]" : undefined
          }
        >
          <DrawerHeader>
            <div className="flex items-start gap-2">
              <DrawerClose
                render={
                  <Button
                    ref={backRef}
                    variant="ghost"
                    size="icon-sm"
                    aria-label="Back to conversation"
                  />
                }
              >
                <ArrowLeftIcon />
              </DrawerClose>
              <div className="flex min-w-0 flex-1 flex-col gap-2">
                <DrawerTitle>Message info</DrawerTitle>
                <DrawerDescription>The studio</DrawerDescription>
              </div>
            </div>
          </DrawerHeader>
          <DrawerPanel>
            <ChatMessageInfoView
              message={
                <ChatMessageBubble side="outgoing">
                  <ChatDemoMessageBody
                    message={message}
                    replyMessage={replyMessage}
                  />
                </ChatMessageBubble>
              }
              metadata={
                <>
                  <time>
                    {message.dateLabel}, {message.time}
                  </time>
                  <ChatDeliveryIndicator
                    status={delivery}
                    label={DELIVERY_LABELS[delivery]}
                  />
                </>
              }
              groups={visibleSections.map(({ key, label, icon: Icon }) => ({
                id: key,
                label,
                icon: (
                  <Icon
                    aria-hidden="true"
                    className={cn(
                      "size-3.5",
                      key === "read"
                        ? "text-sky-600 dark:text-sky-400"
                        : "text-muted-foreground",
                    )}
                  />
                ),
                members: groups[key].map((receipt) => ({
                  id: receipt.member,
                  name: CHAT_MEMBERS[receipt.member].name,
                  avatar: <ChatMemberAvatar member={receipt.member} />,
                  action: (
                    <span className="text-muted-foreground text-xs tabular-nums">
                      {receipt.readAt ?? receipt.deliveredAt ?? "Pending"}
                    </span>
                  ),
                })),
              }))}
            />
          </DrawerPanel>
        </DrawerPopup>
      )}
    </Drawer>
  );
}

"use client";

import { CopyIcon, InfoIcon, PinIcon, Trash2Icon } from "lucide-react";
import type { ReactElement } from "react";
import { useRef, useState } from "react";
import { cn } from "@/registry/default/lib/utils";
import { Avatar, AvatarFallback } from "@/registry/default/ui/avatar";
import { Badge } from "@/registry/default/ui/badge";
import { Button } from "@/registry/default/ui/button";
import { MenuItem, MenuSeparator } from "@/registry/default/ui/menu";
import { ChatCollapsibleMessage } from "../chat/chat-collapsible-message";
import { ChatDeliveryIndicator } from "../chat/chat-delivery-indicator";
import { ChatMessage as ChatMessageView } from "../chat/chat-message";
import { ChatMessageActionToolbar } from "../chat/chat-message-actions";
import { ChatMessageText } from "../chat/chat-message-text";
import { ChatReactionChip } from "../chat/chat-reaction-chip";
import { ChatReactionPicker } from "../chat/chat-reaction-picker";
import { ChatReplyReference } from "../chat/chat-reply-reference";
import { DELIVERY_LABELS, getMessageDelivery } from "./chat-demo-receipts";
import type { ChatMessage, MemberId } from "./chat-demo-state";
import {
  CHAT_EMOJI,
  CHAT_MEMBERS,
  getMessageDeletionReason,
  getMessagePreview,
} from "./chat-demo-state";

export function ChatMemberAvatar({
  member,
  className,
}: {
  member: MemberId;
  className?: string;
}): ReactElement {
  return (
    <Avatar
      aria-hidden="true"
      className={cn("size-7 text-[.625rem]", className)}
    >
      <AvatarFallback className={CHAT_MEMBERS[member].color}>
        {CHAT_MEMBERS[member].initials}
      </AvatarFallback>
    </Avatar>
  );
}

export function ChatDemoMessageBody({
  message,
  replyMessage,
  onJump,
  defaultOpen,
  open,
  onOpenChange,
}: {
  message: ChatMessage;
  replyMessage?: ChatMessage;
  onJump?: (id: number) => void;
  defaultOpen?: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
}): ReactElement {
  const own = message.author === "you";
  return (
    <>
      {message.forwarded && (
        <span className="text-xs italic opacity-65">Forwarded</span>
      )}
      {message.replyTo && (
        <ChatReplyReference
          author={
            replyMessage
              ? CHAT_MEMBERS[replyMessage.author].name
              : "Original message"
          }
          preview={
            replyMessage
              ? getMessagePreview(replyMessage)
              : "Message unavailable"
          }
          onClick={() => onJump?.(message.replyTo ?? message.id)}
          disabled={!replyMessage || !onJump}
        />
      )}
      <ChatCollapsibleMessage
        defaultOpen={defaultOpen}
        open={open}
        onOpenChange={onOpenChange}
        text={message.text}
        side={own ? "outgoing" : "incoming"}
        showMoreLabel="Show more"
        showLessLabel="Show less"
        renderText={(text) => (
          <ChatMessageText
            text={text}
            mentions={Object.values(CHAT_MEMBERS).map(
              (member) => member.handle,
            )}
          />
        )}
      />
    </>
  );
}

export function ChatDemoMessage({
  message,
  recipients,
  entering,
  onEntranceEnd,
  replyMessage,
  grouped,
  groupEnd,
  pinned,
  highlighted,
  replyLifted,
  domId,
  onReply,
  onReact,
  onPin,
  onDelete,
  onCopy,
  onJump,
  onRetry,
  onInfo,
}: {
  message: ChatMessage;
  recipients: readonly MemberId[];
  entering: boolean;
  onEntranceEnd: () => void;
  replyMessage?: ChatMessage;
  grouped: boolean;
  groupEnd: boolean;
  pinned: boolean;
  highlighted: boolean;
  replyLifted: boolean;
  domId: string;
  onReply: (
    id: number,
    source: HTMLDivElement,
    firstInGroup: boolean,
    expanded: boolean,
  ) => void;
  onReact: (id: number, emoji: string) => void;
  onPin: (id: number) => void;
  onDelete: (id: number, trigger: HTMLElement | null) => void;
  onCopy: (text: string) => void;
  onJump: (id: number) => void;
  onRetry: (id: number) => void;
  onInfo: (id: number, trigger: HTMLElement | null) => void;
}): ReactElement {
  const [expanded, setExpanded] = useState(false);
  const moreTriggerRef = useRef<HTMLButtonElement>(null);
  const suppressMenuFocusRef = useRef(false);
  const bubbleRef = useRef<HTMLDivElement>(null);
  const replyToMessage = (): void => {
    if (bubbleRef.current)
      onReply(message.id, bubbleRef.current, !grouped, expanded);
  };
  const initialReactions = useRef(
    new Set(message.reactions.map((reaction) => reaction.emoji)),
  );
  const delivery = getMessageDelivery(message, recipients);
  const own = message.author === "you";
  const member = CHAT_MEMBERS[message.author];
  return (
    <ChatMessageView
      id={domId}
      tabIndex={-1}
      aria-label={`${member.name}, ${message.dateLabel} at ${message.time}`}
      side={own ? "outgoing" : "incoming"}
      author={member.name}
      avatar={<ChatMemberAvatar member={message.author} />}
      grouped={grouped}
      lifted={replyLifted}
      bubble={!message.deletedReason}
      bubbleProps={{ ref: bubbleRef }}
      animateEntrance={entering}
      onAnimationComplete={entering ? onEntranceEnd : undefined}
      highlighted={highlighted}
      actions={
        <ChatMessageActionToolbar
          menuTriggerRef={moreTriggerRef}
          side={own ? "outgoing" : "incoming"}
          toolbarLabel="Message actions"
          reactionPicker={(toolbarRef) => (
            <ChatReactionPicker
              inToolbar
              options={CHAT_EMOJI}
              selectedEmojis={message.reactions
                .filter((reaction) => reaction.members.includes("you"))
                .map((reaction) => reaction.emoji)}
              triggerLabel="React to message"
              triggerTooltip="React"
              popupLabel="Choose a reaction"
              popupAlign={own ? "start" : "end"}
              popupAnchor={toolbarRef}
              onSelect={(emoji) => onReact(message.id, emoji)}
            />
          )}
          replyLabel={`Reply to ${member.name}`}
          replyTooltip="Reply"
          onReply={replyToMessage}
          moreLabel={`More actions for ${member.name}'s message`}
          moreTooltip="More actions"
          menuFinalFocus={() => {
            if (!suppressMenuFocusRef.current) return true;
            suppressMenuFocusRef.current = false;
            return false;
          }}
          menuChildren={
            <>
              <MenuItem onClick={() => onCopy(message.text)}>
                <CopyIcon /> Copy text
              </MenuItem>
              <MenuItem onClick={() => onPin(message.id)}>
                <PinIcon /> {pinned ? "Unpin message" : "Pin message"}
              </MenuItem>
              {own && (
                <MenuItem
                  onClick={() => {
                    suppressMenuFocusRef.current = true;
                    onInfo(message.id, moreTriggerRef.current);
                  }}
                >
                  <InfoIcon /> Message info
                </MenuItem>
              )}
              {getMessageDeletionReason(message) && (
                <>
                  <MenuSeparator />
                  <MenuItem
                    variant="destructive"
                    onClick={() => {
                      suppressMenuFocusRef.current = true;
                      onDelete(message.id, moreTriggerRef.current);
                    }}
                  >
                    <Trash2Icon /> Delete message
                  </MenuItem>
                </>
              )}
            </>
          }
        />
      }
      reactions={
        message.reactions.length > 0 && !message.deletedReason
          ? message.reactions.map((reaction) => (
              <ChatReactionChip
                key={reaction.emoji}
                animateEntrance={!initialReactions.current.has(reaction.emoji)}
                emoji={reaction.emoji}
                count={reaction.members.length}
                reactorLabel={`${reaction.members.length} ${reaction.members.length === 1 ? "reaction" : "reactions"}`}
                popupAlign={own ? "end" : "start"}
                selected={reaction.members.includes("you")}
                label={`${reaction.members.includes("you") ? "Remove" : "Add"} ${reaction.emoji} reaction, ${reaction.members.length} ${reaction.members.length === 1 ? "person" : "people"}`}
                reactorContent={
                  <ul
                    aria-label="People who reacted"
                    className="flex max-h-48 flex-col overflow-y-auto overscroll-contain"
                  >
                    {reaction.members.map((member) => (
                      <li
                        key={member}
                        className="flex items-center gap-2 px-1.5 py-1 text-xs leading-5"
                      >
                        <ChatMemberAvatar
                          member={member}
                          className="size-5 text-[.5625rem]"
                        />
                        <span className="min-w-0 flex-1 truncate">
                          {CHAT_MEMBERS[member].name}
                        </span>
                        {member === "you" && (
                          <Badge variant="secondary" size="sm">
                            You
                          </Badge>
                        )}
                      </li>
                    ))}
                  </ul>
                }
                onClick={() => onReact(message.id, reaction.emoji)}
              />
            ))
          : undefined
      }
      footer={
        groupEnd || message.delivery ? (
          <>
            {pinned && !message.deletedReason && (
              <PinIcon className="size-2.5" aria-label="Pinned" />
            )}
            <time>{message.time}</time>
            {own && !message.deletedReason && (
              <>
                <ChatDeliveryIndicator
                  status={delivery}
                  label={DELIVERY_LABELS[delivery]}
                />
                {message.delivery === "failed" && (
                  <Button
                    variant="ghost"
                    size="xs"
                    onClick={() => onRetry(message.id)}
                  >
                    Retry
                  </Button>
                )}
              </>
            )}
          </>
        ) : undefined
      }
    >
      {message.deletedReason ? (
        <div className="flex items-center gap-1 px-1 py-2 text-muted-foreground text-xs">
          <Trash2Icon className="size-3 opacity-80" aria-hidden="true" />{" "}
          {getMessagePreview(message)}
        </div>
      ) : (
        <ChatDemoMessageBody
          message={message}
          replyMessage={replyMessage}
          onJump={onJump}
          open={expanded}
          onOpenChange={setExpanded}
        />
      )}
    </ChatMessageView>
  );
}

import type { ChatMessage, ChatReceipt, MemberId } from "./chat-demo-state";
import { OTHER_MEMBERS } from "./chat-demo-state";

export type MessageDelivery = NonNullable<ChatMessage["delivery"]>;

export const DELIVERY_LABELS: Record<MessageDelivery, string> = {
  sending: "Sending",
  sent: "Sent",
  delivered: "Delivered to everyone",
  read: "Read by everyone",
  failed: "Not sent",
};

export function getMessageReceipts(
  message: ChatMessage,
  recipients: readonly MemberId[] = OTHER_MEMBERS,
): ChatReceipt[] {
  if (message.receipts) {
    const receiptsByMember = new Map(
      message.receipts.map((receipt) => [receipt.member, receipt]),
    );
    return recipients.map(
      (member) => receiptsByMember.get(member) ?? { member },
    );
  }
  return recipients.map((member) => ({
    member,
    deliveredAt:
      message.delivery === "delivered" || message.delivery === "read"
        ? message.time
        : undefined,
    readAt: message.delivery === "read" ? message.time : undefined,
  }));
}

export function getMessageDelivery(
  message: ChatMessage,
  recipients?: readonly MemberId[],
): MessageDelivery {
  if (message.delivery === "sending" || message.delivery === "failed")
    return message.delivery;
  const receipts = getMessageReceipts(message, recipients);
  if (receipts.length && receipts.every((receipt) => receipt.readAt))
    return "read";
  if (
    receipts.length &&
    receipts.every((receipt) => receipt.deliveredAt || receipt.readAt)
  )
    return "delivered";
  return "sent";
}

export function groupMessageReceipts(
  message: ChatMessage,
  recipients?: readonly MemberId[],
): {
  read: ChatReceipt[];
  delivered: ChatReceipt[];
  pending: ChatReceipt[];
} {
  const groups: ReturnType<typeof groupMessageReceipts> = {
    read: [],
    delivered: [],
    pending: [],
  };
  for (const receipt of getMessageReceipts(message, recipients)) {
    if (receipt.readAt) groups.read.push(receipt);
    else if (receipt.deliveredAt) groups.delivered.push(receipt);
    else groups.pending.push(receipt);
  }
  return groups;
}

"use client";

import type { ReactElement, RefObject } from "react";
import {
  ChatReplyPreview,
  type ChatReplyTarget,
} from "../chat/chat-reply-preview";
import { ChatDemoMessageBody, ChatMemberAvatar } from "./chat-demo-message";
import type { ChatMessage } from "./chat-demo-state";
import { CHAT_MEMBERS } from "./chat-demo-state";

export type ChatReplyFocusTarget = ChatReplyTarget & {
  messageId: number;
  expanded: boolean;
};

export function ChatDemoReplyFocus({
  target,
  message,
  replyMessage,
  dismissalRef,
  onCancel,
}: {
  target: ChatReplyFocusTarget;
  message: ChatMessage;
  replyMessage?: ChatMessage;
  dismissalRef: RefObject<"cancel" | "send">;
  onCancel: () => void;
}): ReactElement {
  const own = message.author === "you";
  return (
    <ChatReplyPreview
      target={target}
      side={own ? "outgoing" : "incoming"}
      avatar={<ChatMemberAvatar member={message.author} />}
      author={own ? "your message" : CHAT_MEMBERS[message.author].name}
      replyLabel={
        own
          ? "Reply to your message"
          : `Reply to ${CHAT_MEMBERS[message.author].name}`
      }
      cancelLabel="Cancel reply"
      dismissalRef={dismissalRef}
      onCancel={onCancel}
    >
      <ChatDemoMessageBody
        defaultOpen={target.expanded}
        message={message}
        replyMessage={replyMessage}
      />
    </ChatReplyPreview>
  );
}

"use client";

import {
  BanIcon,
  CircleAlertIcon,
  LockIcon,
  LogOutIcon,
  MessageCircleIcon,
  UserXIcon,
} from "lucide-react";
import type { ReactElement } from "react";
import { Button } from "@/registry/default/ui/button";
import { ChatEmptyState, ChatLoadingState } from "../chat/chat-states";
import type { ChatScenario } from "./chat-demo-state";

export function ChatTimelineState({
  scenario,
  onRecover,
  memberCount,
  joined,
  onJoin,
}: {
  scenario: ChatScenario;
  onRecover: () => void;
  memberCount: number;
  joined: boolean;
  onJoin: () => void;
}): ReactElement | null {
  if (scenario === "loading")
    return (
      <ChatLoadingState label="Loading conversation">
        <Button variant="outline" size="sm" onClick={onRecover}>
          Finish loading preview
        </Button>
      </ChatLoadingState>
    );
  const content = {
    empty: {
      title: joined ? "A little hello goes a long way" : "Join the event chat",
      description: joined
        ? "Start the conversation. Everyone in the group can join in."
        : "Talk with the host and other guests who are going. Only people who join can read or send messages.",
      Icon: MessageCircleIcon,
    },
    error: {
      title: "Couldn’t load the conversation",
      description: "Your draft is safe. Try loading the messages again.",
      Icon: CircleAlertIcon,
    },
    "access-lost": {
      title: "This conversation is no longer available",
      description:
        "You no longer have access. Contact the group admin if this seems wrong.",
      Icon: LockIcon,
    },
    removed: {
      title: "You were removed from this chat",
      description:
        "A host removed you. You can rejoin through your ticket invitation. Your ticket for the event is still valid.",
      Icon: UserXIcon,
    },
    banned: {
      title: "You were banned from this chat",
      description:
        "You can’t rejoin unless a host lifts the ban. Your ticket for the event is still valid.",
      Icon: BanIcon,
    },
    left: {
      title: "You left this chat",
      description:
        "You’ll no longer receive messages from this group. Your ticket for the event is still valid.",
      Icon: LogOutIcon,
    },
  };
  if (
    scenario !== "empty" &&
    scenario !== "error" &&
    scenario !== "access-lost" &&
    scenario !== "removed" &&
    scenario !== "banned" &&
    scenario !== "left"
  )
    return null;
  const { title, description, Icon } = content[scenario];
  return (
    <ChatEmptyState
      title={title}
      description={description}
      icon={<Icon aria-hidden="true" />}
    >
      {scenario === "empty" && !joined && (
        <div className="flex flex-col items-center gap-2">
          <Button onClick={onJoin}>Join chat</Button>
          <p className="text-muted-foreground text-xs">
            {memberCount} {memberCount === 1 ? "person is" : "people are"}{" "}
            already in the chat
          </p>
        </div>
      )}
      {scenario === "error" && (
        <Button variant="outline" size="sm" onClick={onRecover}>
          Try again
        </Button>
      )}
      {(scenario === "left" || scenario === "removed") && (
        <Button onClick={onRecover}>Rejoin chat</Button>
      )}
    </ChatEmptyState>
  );
}

